<template>
 <div class="xp-lab-backdrop" @keydown.stop @keyup.stop @keydown.esc="close">
  <section ref="dialog" class="xp-lab" :class="{'is-transferring':transferring}" role="dialog" aria-modal="true" aria-labelledby="xp-lab-title" @keydown.tab="trap" @pointermove="move" @pointerup="finish" @pointercancel="cancelDrag" @lostpointercapture="cancelDrag">
   <header class="xp-lab-header"><div class="xp-lab-seal" aria-hidden="true">⇄</div><div><small>ROCHEBRUME · LABORATOIRE</small><h2 id="xp-lab-title">Échange d’expérience</h2></div><button ref="close" class="xp-close" :disabled="busy || transferring" aria-label="Fermer le laboratoire" @click="close">×</button></header>
   <div class="xp-lab-content">
    <p class="xp-intro">Deux Pokémon de la même espèce. Leurs expériences s’inversent, chacun garde son identité.</p>
    <div class="xp-specimens">
     <button v-for="(pokemon,index) in selected" :key="index" class="xp-specimen" :class="{'is-active':active===index,'is-drop':drag && drag.to && drag.to.index===index}" :data-xp-slot="index" data-pc-drop="team" :data-pc-index="index" :disabled="frozen" :aria-label="'Choisir le Pokémon '+(index+1)" @click="active=index">
      <small class="xp-label">SPÉCIMEN {{ index===0?'A':'B' }} <span>{{ active===index?'Sélection en cours':'Toucher pour sélectionner' }}</span></small>
      <template v-if="pokemon"><pokemon-portrait :src="sprite(pokemon)"/><strong>{{ pokemon.name }} <potential-star :value="pokemon.k"/></strong><span class="xp-current">Niveau {{ pokemon.level }} <span>· {{ format(pokemon.experience) }} XP</span></span><small>{{ sourceName(pokemon) }}</small></template>
      <div v-else class="xp-empty"><span aria-hidden="true">＋</span><strong>Dépose un Pokémon</strong><small>ou choisis-le dans la liste</small></div>
      <div v-if="offer" class="xp-after"><span>APRÈS L’ÉCHANGE</span><strong>Niv. {{ offer.after[index].level }}</strong><small>{{ format(offer.after[index].experience) }} XP</small></div>
     </button>
     <span class="xp-link" aria-hidden="true"><i></i><b>⇄</b><i></i></span>
    </div>
    <div v-if="receipt" class="xp-receipt" role="status" data-xp-success><strong>{{ transferring?'Transfert en cours…':'Échange terminé' }}</strong><span>{{ transferring?'Les expériences se croisent.': 'Les niveaux et les statistiques ont été recalculés.' }}</span><small>IV, EV, talent, capacités, objet et nature conservés. Aucun soin offert.</small></div>
    <template v-else-if="!offer">
     <div class="xp-roster-toolbar"><div class="xp-sources" role="group" aria-label="Provenance des Pokémon"><button :class="{'is-selected':source==='team'}" :disabled="busy" @click="source='team';page=0">Équipe</button><button :class="{'is-selected':source==='box'}" :disabled="busy" @click="source='box';page=0">PC</button></div><label v-if="source==='box'" class="xp-box">Boîte<select v-model.number="box" :disabled="busy" @change="page=0"><option :value="-1">Toutes les boîtes</option><option v-for="n in 20" :key="n" :value="n-1">Boîte {{ n }}</option></select></label><label class="xp-search"><span class="sr-only">Rechercher un Pokémon</span><input v-model="search" :disabled="busy" placeholder="Chercher un Pokémon…" @input="page=0"></label></div>
     <p class="xp-roster-help">{{ active===1 && selected[0]?'Même espèce que '+selected[0].speciesName+' · ':'' }}Touche une fiche ou glisse sa poignée vers A ou B.</p>
     <div class="xp-roster pc-body" data-xp-roster>
      <div v-for="pokemon in pageRows" :key="pokemon.uuid" class="xp-roster-card" :class="{'is-chosen':ids.includes(pokemon.uuid)}">
       <button class="xp-pick" :data-xp-pokemon="pokemon.uuid" :disabled="busy" @pointerdown="desktopDrag($event,pokemon)" @click="pick(pokemon,active)"><pokemon-portrait :src="sprite(pokemon)"/><span><strong>{{ pokemon.name }}</strong><small>Niv. {{ pokemon.level }} · {{ format(pokemon.experience) }} XP</small><small>{{ sourceName(pokemon) }}</small></span><potential-star :value="pokemon.k"/></button>
       <button class="xp-drag-handle" :disabled="busy" :aria-label="'Glisser '+pokemon.name" @pointerdown.prevent="start($event,pokemon)" @click="pick(pokemon,active)">⠿</button>
      </div>
      <p v-if="!pageRows.length" class="xp-no-results">{{ active===1 && selected[0]?'Aucun autre '+selected[0].speciesName+' ici. Essaie les autres boîtes.':'Aucun Pokémon à afficher.' }}</p>
     </div>
     <div v-if="filtered.length>30" class="xp-pagination"><button :disabled="page===0 || busy" @click="page--">Précédent</button><span>{{ page+1 }} / {{ pages }}</span><button :disabled="page+1>=pages || busy" @click="page++">Suivant</button></div>
    </template>
    <div v-else-if="!receipt" class="xp-preview" data-xp-preview><strong>Vérifie le transfert avant de confirmer.</strong><p>Seule l’expérience totale change de propriétaire. Les niveaux peuvent monter ou descendre, les statistiques suivent. Les capacités et les évolutions restent telles quelles.</p><div><span>Solde après l’échange</span><strong>{{ format(state.money-state.price) }} ₽</strong></div></div>
    <p v-if="offer && !receipt && state.money<state.price" class="xp-error">Solde insuffisant : il te faut 1 000 000 ₽ pour confirmer.</p>
    <p v-if="error" class="xp-error" role="alert">{{ error }}</p><p v-else-if="!offer && selected[0] && selected[1] && !compatible" class="xp-error">{{ selected[0].pokemonId!==selected[1].pokemonId?'Choisis deux Pokémon de la même espèce.':'Ces Pokémon ont déjà la même expérience.' }}</p>
   </div>
   <footer><div class="xp-price"><small>PRIX DU TRANSFERT</small><strong>{{ format(state.price) }} ₽</strong><span>Ton solde : {{ format(state.money) }} ₽</span></div><div class="xp-actions"><template v-if="receipt"><button class="xp-primary" :disabled="busy || transferring" @click="newExchange">Nouvel échange</button></template><template v-else-if="offer"><button :disabled="busy || transferring || !!pending" @click="offer=null;error=''">Modifier</button><button class="xp-primary" data-xp-confirm :disabled="busy || transferring || state.money<state.price" @click="confirm">{{ busy?'Enregistrement…':pending?'Vérifier le résultat':'Confirmer · '+format(state.price)+' ₽' }}</button></template><button v-else class="xp-primary" data-xp-preview-button :disabled="!compatible || busy" @click="preview">{{ busy?'Calcul…':'Voir l’aperçu' }}</button></div></footer>
  </section>
  <div v-if="drag" class="xp-ghost" :style="{left:drag.x+'px',top:drag.y+'px'}" aria-hidden="true"><pokemon-portrait :src="sprite(drag.pokemon)"/>{{ drag.pokemon.name }}</div>
 </div>
</template>
<script>
import PokemonPortrait from '../PokemonPortrait.vue';
import PotentialStar from '../PotentialStar.vue';
import {createComputerDrag} from '@/services/computerDrag';
export default {
 name:'ExperienceExchangeLab',components:{PokemonPortrait,PotentialStar},
 props:{panel:{type:Object,required:true},command:{type:Function,required:true},animationsEnabled:{type:Boolean,default:true}},
 data(){return {state:this.panel,ids:[null,null],active:0,source:'team',box:-1,search:'',page:0,busy:false,error:'',offer:null,receipt:null,pending:null,transferring:false,drag:null};},
 computed:{
  frozen(){return this.busy || !!this.offer || !!this.receipt;},
  selected(){return this.ids.map(id=>this.state.roster.find(p=>p.uuid===id)||null);},
  compatible(){const [a,b]=this.selected;return !!a && !!b && a.uuid!==b.uuid && a.pokemonId===b.pokemonId && a.experience!==b.experience;},
  filtered(){return this.state.roster.filter(p=>p.source===this.source && (this.source!=='box' || this.box<0 || p.box===this.box) && (this.active!==1 || !this.selected[0] || p.pokemonId===this.selected[0].pokemonId && p.uuid!==this.ids[0]) && (p.name+' '+p.speciesName).toLocaleLowerCase('fr').includes(this.search.toLocaleLowerCase('fr')));},
  pages(){return Math.max(1,Math.ceil(this.filtered.length/30));},pageRows(){return this.filtered.slice(Math.min(this.page,this.pages-1)*30,(Math.min(this.page,this.pages-1)+1)*30);}
 },
 mounted(){this._previousFocus=document.activeElement;this._drag=createComputerDrag({root:this.$refs.dialog,changed:s=>{this.drag=s;},drop:p=>this.pick(this.state.roster.find(x=>x.uuid===p.pokemonUuid),p.to.index,true),navigateBox:()=>{},ended:()=>{this._suppressUntil=performance.now()+500;}});window.addEventListener('blur',this.cancelDrag);document.addEventListener('visibilitychange',this.cancelDrag);this.$refs.close.focus({preventScroll:true});},
 beforeDestroy(){clearTimeout(this._animationTimer);this.cancelDrag();window.removeEventListener('blur',this.cancelDrag);document.removeEventListener('visibilitychange',this.cancelDrag);if(this._previousFocus?.isConnected)this._previousFocus.focus({preventScroll:true});},
 methods:{
  format(n){return Number(n).toLocaleString('fr-FR');},sprite(p){return this.$pokemonSprite(p);},sourceName(p){return p.source==='team'?'Équipe':'Boîte '+(p.box+1)+' · place '+(p.slot+1);},
  close(){if(!this.busy && !this.transferring)this.$emit('close');},
  pick(p,index,fromDrop=false){if(this.frozen || !p || index<0 || index>1 || !fromDrop && performance.now()<(this._suppressUntil||0))return;if(this.ids[1-index]===p.uuid)this.$set(this.ids,1-index,null);this.$set(this.ids,index,p.uuid);if(index===0 && this.selected[1]?.pokemonId!==p.pokemonId)this.$set(this.ids,1,null);this.error='';this.active=index===0?1:index;this.page=0;},
  desktopDrag(e,p){if(e.pointerType!=='touch')this.start(e,p);},start(e,p){if(!this.frozen)this._drag.start(e,p,{kind:p.source});},move(e){this._drag?.move(e);},finish(e){this._drag?.finish(e);},cancelDrag(){this._drag?.cancel();},
  async preview(){if(!this.compatible || this.busy)return;this.busy=true;this.error='';const result=await this.command('experienceExchange:preview',{firstUuid:this.ids[0],secondUuid:this.ids[1]});this.busy=false;if(!result.success){this.error=result.message;return;}this.offer=result.offer;this.state={...this.state,money:result.money};},
  async confirm(){if(!this.offer || this.busy)return;this.busy=true;this.error='';if(!this.pending)this.pending={requestId:crypto.randomUUID(),firstUuid:this.ids[0],secondUuid:this.ids[1],price:this.offer.price,expected:this.offer.expected};const result=await this.command('experienceExchange:confirm',this.pending);this.busy=false;if(!result.success){this.error=result.message;if(!result.uncertain){this.pending=null;this.offer=null;}return;}this.pending=null;this.receipt=result.receipt;this.transferring=this.animationsEnabled && !matchMedia('(prefers-reduced-motion: reduce)').matches;const finish=()=>{this.state={...this.state,...result};this.transferring=false;};if(this.transferring)this._animationTimer=setTimeout(finish,1000);else finish();},
  newExchange(){this.ids=[null,null];this.active=0;this.offer=null;this.receipt=null;this.error='';this.pending=null;},
  trap(event){const list=[...this.$refs.dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(n=>n.getClientRects().length);if(!list.length)return;const first=list[0],last=list.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}
 }
};
</script>
